/* ===================== BÀI 23 · Truyền tham số và bảo toàn thanh ghi ===================== */
/* Bài 23 · Truyền tham số và bảo toàn thanh ghi (AMTS-EMB-002-M06-L03, X86-023) — sinh bởi tools/author/mpu8086/l23.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P23=[{"label": "Ví dụ: tham số và kết quả qua thanh ghi", "code": "; Ví dụ 1: tham số và kết quả qua thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1200H               ; tham số 1\n        MOV     BX, 0034H               ; tham số 2\n        CALL    tong2                   ; kết quả trong AX\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; tong2: vào AX, BX; ra AX = AX + BX; giữ mọi thanh ghi khác\ntong2   PROC    NEAR\n        ADD     AX, BX\n        RET\ntong2   ENDP\n        END     MAIN\n", "input": "", "note": "Hợp đồng qua thanh ghi: AX, BX vào; AX ra. CALL tong2 (19) + ADD AX, BX (3) + RET (8) = 30 chu kỳ, không truy cập bộ nhớ nào ngoài địa chỉ trả về. Xem kq = 1234h ở phần Bộ nhớ. Đoán trước: ngay trước MOV kq, AX, AX bằng bao nhiêu? Đáp án 1234h."}, {"label": "Ví dụ: tham số qua ngăn xếp, khung BP", "code": "; Ví dụ 2: tham số qua ngăn xếp, khung BP, RET 4\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1200H\nb       DW      0034H\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        PUSH    a                       ; tham số 1 (cất trước)\n        PUSH    b                       ; tham số 2\n        CALL    tong2\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; tong2(x, y): ra AX = x + y; tự dọn 4 byte tham số\ntong2   PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP                  ; [BP+2] = địa chỉ trả về\n        MOV     AX, [BP+6]              ; x\n        ADD     AX, [BP+4]              ; y\n        POP     BP\n        RET     4                       ; trở về và SP + 4\ntong2   ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới MOV AX, [BP+6] và nhìn phần Ngăn xếp: bốn word từ BP lên là BP cũ, địa chỉ trả về 0010h, y = 0034h, x = 1200h. [BP+6] đọc x, [BP+4] đọc y (mỗi lần EA = BP + 8 bit = 9 chu kỳ). RET 4 (C2 04 00, 12 chu kỳ) trở về và bỏ 4 byte: SP về 0110h. Đoán trước: sau MOV BP, SP, BP bằng bao nhiêu? Đáp án 0108h."}, {"label": "Ví dụ: người gọi dọn tham số", "code": "; Ví dụ 3: người gọi dọn tham số (ADD SP, 4)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1200H\nb       DW      0034H\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        PUSH    a\n        PUSH    b\n        CALL    tong2\n        ADD     SP, 4                   ; người gọi bỏ 2 tham số\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ntong2   PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     AX, [BP+6]\n        ADD     AX, [BP+4]\n        POP     BP\n        RET                             ; RET thường: không dọn tham số\ntong2   ENDP\n        END     MAIN\n", "input": "", "note": "Cùng phép cộng nhưng thủ tục RET thường, người gọi ADD SP, 4 (83 C4 04). Tổng chu kỳ bằng Ví dụ 2 (202): RET 8 + ADD 4 = RET 4 12. Mã dài hơn 1 byte, và mỗi chỗ gọi thêm 3 byte. Đoán trước: ngay sau RET (trước ADD SP, 4), SP bằng bao nhiêu? Đáp án 010Ch."}, {"label": "Lỗi: đếm sai vị trí tham số", "code": "; Ví dụ 4 (lỗi): đếm sai vị trí tham số trong khung\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1200H\nb       DW      0034H\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        PUSH    a\n        PUSH    b\n        CALL    tong2\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ntong2   PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     AX, [BP+4]              ; SAI: tưởng là x, thật ra là y\n        ADD     AX, [BP+2]              ; SAI: đây là địa chỉ trả về\n        POP     BP\n        RET     4\ntong2   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: đếm vị trí tham số như thể không có địa chỉ trả về. [BP+4] là y (0034h), [BP+2] là địa chỉ trả về (0010h), nên kq = 0044h thay vì 1234h; không có thông báo lỗi nào. Sửa: [BP+6] là x, [BP+4] là y. Đoán trước: [BP+2] chứa gì? Đáp án 0010h, địa chỉ trả về."}, {"label": "Lỗi: không ai dọn tham số", "code": "; Ví dụ 5 (lỗi): không ai dọn tham số, SP trôi dần\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 3\nlap:\n        PUSH    CX                      ; tham số 1\n        PUSH    CX                      ; tham số 2\n        CALL    tong2                   ; SAI: thủ tục RET thường,\n        MOV     kq, AX                  ; người gọi cũng không ADD SP\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ntong2   PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     AX, [BP+6]\n        ADD     AX, [BP+4]\n        POP     BP\n        RET\ntong2   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: thủ tục RET thường và người gọi không ADD SP. Mỗi vòng để lại 2 tham số (4 byte): SP từ 0110h xuống 0104h sau 3 vòng. Chương trình vẫn kết thúc vì INT 21h hàm 4Ch không cần SP đúng; trong vòng lặp dài, ngăn xếp sẽ tràn như Bài 21. Sửa: RET 4 hoặc ADD SP, 4 sau CALL. Đoán trước: SP lúc kết thúc bằng bao nhiêu? Đáp án 0104h."}, {"label": "Lỗi: thủ tục làm hỏng CX của vòng lặp", "code": "; Ví dụ 6 (lỗi): thủ tục làm hỏng CX của người gọi\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     BL, 7                   ; số đầu tiên\n        MOV     CX, 3                   ; in 3 số\nlap:\n        MOV     AL, BL\n        CALL    in2so\n        INC     BL\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; in2so: in AL (0..99) bằng 2 chữ số và 1 dấu cách\nin2so   PROC    NEAR\n        MOV     AH, 0\n        MOV     CL, 10                  ; SAI: ghi đè CL của vòng lặp\n        DIV     CL                      ; AL = chục, AH = đơn vị\n        MOV     DX, AX\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, DH\n        ADD     DL, '0'\n        INT     21H\n        MOV     DL, ' '\n        INT     21H\n        RET\nin2so   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: in2so ghi CL = 10 để chia. Sau lời gọi, CX = 000Ah thay vì 3, 2, 1; LOOP giảm còn 9 nhưng lời gọi sau lại đặt 10: vòng lặp không dừng, in mãi 07 08 09 10 … tới giới hạn của trình mô phỏng. DIV CL tốn 80 chu kỳ (cận dưới của 80–90). Sửa ở Ví dụ 7. Đoán trước: sau lời gọi đầu tiên, CX bằng bao nhiêu? Đáp án 000Ah."}, {"label": "Sửa: thủ tục tự cất và khôi phục CX", "code": "; Ví dụ 7 (sửa): thủ tục tự cất và khôi phục CX\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     BL, 7\n        MOV     CX, 3\nlap:\n        MOV     AL, BL\n        CALL    in2so\n        INC     BL\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; in2so: vào AL (0..99). Hỏng AX, DX. Giữ BX, CX.\nin2so   PROC    NEAR\n        PUSH    CX                      ; cất thanh ghi mình sẽ dùng\n        MOV     AH, 0\n        MOV     CL, 10\n        DIV     CL\n        MOV     DX, AX\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, DH\n        ADD     DL, '0'\n        INT     21H\n        MOV     DL, ' '\n        INT     21H\n        POP     CX                      ; khôi phục trước RET\n        RET\nin2so   ENDP\n        END     MAIN\n", "input": "", "note": "Bản sửa của Ví dụ 6: PUSH CX ngay đầu in2so và POP CX ngay trước RET (thêm 11 + 8 chu kỳ mỗi lời gọi). Phần Ngăn xếp có 2 word khi đang ở trong thủ tục: CX đã cất và địa chỉ trả về. Màn hình in 07 08 09. Đoán trước: sau lời gọi đầu tiên, CX bằng bao nhiêu? Đáp án 0003h."}];
const sim23=makeX86Sim(document.getElementById("x86-l23"),{id:"s23",presets:P23,file:"BAI23.ASM"});
makeX86Ex(document.getElementById("ex-l23"),sim23,[{"t": "Thủ tục max2 qua ngăn xếp", "d": "MAIN đọc 3 cặp chữ số; với mỗi cặp x, y nó PUSH x, PUSH y, gọi max2 rồi in AL. Viết thủ tục max2 theo hợp đồng: ra AX = số lớn hơn trong hai tham số; thủ tục tự dọn tham số bằng RET 4; giữ nguyên BX, CX, DX, SI, DI, BP. Không sửa MAIN (MAIN đặt sẵn BX = 1234h, SI = 5678h, DI = 9ABCh, BP = 4321h, DH = 77h và bài chấm kiểm các giá trị này lúc kết thúc; MAIN cất bộ đếm vòng trên ngăn xếp nên chỉ chạy đúng khi max2 dọn đúng 4 byte tham số). Code mẫu mới trả về y. Ví dụ gõ 374155 thì in 745.", "start": "; Bài tập 1: thủ tục max2 nhận tham số qua ngăn xếp\n; Hợp đồng: người gọi PUSH x rồi PUSH y (word 0..9),\n; CALL max2. Ra: AX = số lớn hơn. max2 tự dọn tham số\n; (RET 4), giữ BX, CX, DX, SI, DI, BP. KHÔNG sửa MAIN.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     BX, 1234H               ; MAIN đặt sẵn các thanh ghi mà\n        MOV     SI, 5678H               ; hợp đồng bắt max2 giữ nguyên;\n        MOV     DI, 9ABCH               ; bài chấm kiểm BX, SI, DI, BP, DH\n        MOV     BP, 4321H               ; lúc kết thúc chương trình\n        MOV     DX, 7700H               ; (MAIN chỉ đổi DL khi in)\n        MOV     CX, 3                   ; 3 cặp chữ số\nlap:\n        PUSH    CX                      ; MAIN tự cất bộ đếm vòng\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        PUSH    AX                      ; x\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        PUSH    AX                      ; y\n        CALL    max2\n        MOV     DL, AL\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        POP     CX                      ; đúng khi max2 đã dọn tham số\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nmax2    PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     AX, [BP+4]              ; mới lấy y; hãy so với x\n        POP     BP\n        RET     4                       ; dọn 2 tham số\nmax2    ENDP\n        END     MAIN\n", "tests": [{"in": "374155", "out": "745", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}, {"in": "000000", "out": "000", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}, {"in": "999999", "out": "999", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}, {"in": "091827", "out": "987", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}, {"in": "506172", "out": "567", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}, {"in": "334455", "out": "345", "regs": {"BX": 4660, "SI": 22136, "DI": 39612, "BP": 17185, "DH": 119}}]}, {"t": "Tổng mảng có hợp đồng", "d": "MAIN đọc n (phím 1–9) rồi n chữ số vào mảng byte mang, PUSH địa chỉ mang, PUSH n, gọi tong, ghi AX vào kq. Sau lời gọi MAIN còn dùng CX (ghi CL vào dem) và SI (ghi byte [SI] vào dau). Sửa thủ tục tong cho đúng hợp đồng: AX = tổng không dấu các phần tử; giữ BX, CX, DX, SI, DI, BP; tự dọn tham số (RET 4). Không sửa MAIN.", "start": "; Bài tập 2: thủ tục tong cộng mảng byte theo hợp đồng\n; tong(dc, n): người gọi PUSH địa chỉ đầu mảng rồi PUSH n.\n; Ra: AX = tổng không dấu. Giữ BX, CX, DX, SI, DI, BP.\n; Tự dọn tham số (RET 4). tong trong code mẫu cộng đúng\n; nhưng làm hỏng CX, SI mà MAIN còn dùng. Chỉ sửa tong.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      9 DUP(?)\nkq      DW      ?\ndem     DB      ?                       ; MAIN ghi CL sau lời gọi\ndau     DB      ?                       ; MAIN ghi [SI] sau lời gọi\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; n = '1'..'9'\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     DI, AX                  ; DI = n\n        MOV     CX, AX\n        MOV     BX, OFFSET mang\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     [BX], AL\n        INC     BX\n        LOOP    doc\n        MOV     SI, OFFSET mang\n        MOV     CX, DI\n        PUSH    SI                      ; tham số 1: địa chỉ mảng\n        PUSH    CX                      ; tham số 2: n\n        CALL    tong\n        MOV     kq, AX\n        MOV     dem, CL                 ; cần CX = n như trước lời gọi\n        MOV     AL, [SI]                ; cần SI = địa chỉ mảng\n        MOV     dau, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ntong    PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     SI, [BP+6]              ; địa chỉ mảng\n        MOV     CX, [BP+4]              ; n\n        XOR     AX, AX\ncong:\n        ADD     AL, [SI]\n        ADC     AH, 0\n        INC     SI\n        LOOP    cong\n        POP     BP\n        RET     4\ntong    ENDP\n        END     MAIN\n", "tests": [{"in": "3123", "mem": [{"at": "kq", "word": 6}, {"at": "dem", "bytes": [3]}, {"at": "dau", "bytes": [1]}]}, {"in": "19", "mem": [{"at": "kq", "word": 9}, {"at": "dem", "bytes": [1]}, {"at": "dau", "bytes": [9]}]}, {"in": "9999999999", "mem": [{"at": "kq", "word": 81}, {"at": "dem", "bytes": [9]}, {"at": "dau", "bytes": [9]}]}, {"in": "500000", "mem": [{"at": "kq", "word": 0}, {"at": "dem", "bytes": [5]}, {"at": "dau", "bytes": [0]}]}, {"in": "40919", "mem": [{"at": "kq", "word": 19}, {"at": "dem", "bytes": [4]}, {"at": "dau", "bytes": [0]}]}, {"in": "258", "mem": [{"at": "kq", "word": 13}, {"at": "dem", "bytes": [2]}, {"at": "dau", "bytes": [5]}]}]}, {"t": "Truyền tham số rẻ hơn", "d": "Đọc lần lượt 4 phím chữ số và ghi số thập phân 4 chữ số đó (0–9999) vào biến word kq: phím 1, 2, 3, 4 cho kq = 1234. Không in gì; kết thúc bằng INT 21h hàm 4Ch. Code mẫu đúng nhưng mỗi lần gọi thủ tục them đi qua ngăn xếp và khung BP. Viết lại để đạt cả giới hạn chu kỳ và byte mã; có thể tự đặt hợp đồng mới cho them.", "start": "; Bài tập 3: đổi 4 chữ số thành số, gọi thủ tục rẻ hơn\n; Bản này đúng nhưng truyền tham số qua ngăn xếp có khung\n; BP. Hãy viết lại cho đạt giới hạn chu kỳ và byte mã.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX                  ; số đang dựng\n        MOV     CX, 4\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        PUSH    BX                      ; tham số so\n        PUSH    AX                      ; tham số cs\n        CALL    them\n        MOV     BX, AX\n        LOOP    doc\n        MOV     kq, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; them(so, cs): AX = so × 10 + cs. Giữ BX, CX, DX. RET 4.\nthem    PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        PUSH    DX\n        MOV     AX, [BP+6]              ; so\n        MOV     DX, 10\n        MUL     DX                      ; DX:AX = so × 10\n        ADD     AX, [BP+4]              ; + cs\n        POP     DX\n        POP     BP\n        RET     4\nthem    ENDP\n        END     MAIN\n", "tests": [{"in": "1234", "mem": [{"at": "kq", "word": 1234}]}, {"in": "0000", "mem": [{"at": "kq", "word": 0}]}, {"in": "9999", "mem": [{"at": "kq", "word": 9999}]}, {"in": "0500", "mem": [{"at": "kq", "word": 500}]}, {"in": "0007", "mem": [{"at": "kq", "word": 7}]}, {"in": "6553", "mem": [{"at": "kq", "word": 6553}]}], "perf": {"cycles": 1100, "bytes": 50}}]);

makeQuiz("quiz23","score23",[{"q": "Thủ tục gần được gọi sau <code>PUSH a<\/code>, <code>PUSH b<\/code>, <code>PUSH c<\/code>, <code>CALL f<\/code>. Trong f, sau <code>PUSH BP<\/code> / <code>MOV BP, SP<\/code>, tham số a nằm ở đâu?", "o": ["<code>[BP+4]<\/code>", "<code>[BP+6]<\/code>", "<code>[BP+2]<\/code>", "<code>[BP+8]<\/code>"], "a": 3, "e": "Từ BP lên: [BP] = BP cũ, [BP+2] = địa chỉ trả về, [BP+4] = c (cất sau cùng), [BP+6] = b, [BP+8] = a. Nhầm phổ biến là coi tham số đầu tiên luôn ở [BP+4]."}, {"q": "Đoạn sau chạy với a = 0005h, b = 0003h. Thủ tục là PROC <b>FAR<\/b>. Sau lời gọi, AX bằng bao nhiêu?<pre class=\"mp-asm\">        PUSH    a\n        PUSH    b\n        CALL    f\n        ...\nf       PROC    FAR\n        PUSH    BP\n        MOV     BP, SP\n        MOV     AX, [BP+6]\n        SUB     AX, [BP+8]\n        POP     BP\n        RET     4\nf       ENDP<\/pre>", "o": ["0002h (a − b = 5 − 3)", "0003h (chỉ đọc được b)", "FFFEh (b − a = 3 − 5)", "Không xác định vì [BP+6] là CS cũ"], "a": 2, "e": "Lời gọi xa cất CS và IP, nên [BP+2] = IP, [BP+4] = CS, [BP+6] = b (cất sau cùng), [BP+8] = a. AX = 3 − 5 = −2 = FFFEh. Đọc theo thói quen của lời gọi gần sẽ lấy nhầm CS."}, {"q": "Thủ tục kết thúc bằng <code>RET<\/code> thường; người gọi viết <code>PUSH x<\/code> / <code>PUSH y<\/code> / <code>CALL f<\/code> rồi <code>ADD SP, 4<\/code>. Nếu sửa thủ tục thành <code>RET 4<\/code> mà giữ nguyên người gọi, điều gì xảy ra?", "o": ["SP sau ADD cao hơn đúng 4 byte: các lần POP/RET sau lấy nhầm word", "Không đổi gì vì RET 4 và ADD SP, 4 bù trừ cho nhau", "SP thấp hơn 4 byte sau mỗi lời gọi, ngăn xếp trôi dần", "Trình dịch báo lỗi vì RET 4 không đi với ADD SP, 4"], "a": 0, "e": "Hai bên cùng dọn: RET 4 đã bỏ 4 byte, ADD SP, 4 bỏ thêm 4 byte nữa, nên SP vượt lên trên vùng của người gọi. Thiếu cả hai mới làm SP trôi xuống (Ví dụ 5). Trình dịch không kiểm hợp đồng."}, {"q": "Hợp đồng: thủ tục <code>dem<\/code> trả kết quả trong AX và phải giữ BX, CX. Phần đầu và cuối nào đúng?", "o": ["<code>PUSH AX<\/code> / <code>PUSH BX<\/code> / <code>PUSH CX<\/code> … <code>POP CX<\/code> / <code>POP BX<\/code> / <code>POP AX<\/code> / <code>RET<\/code>", "<code>PUSH BX<\/code> / <code>PUSH CX<\/code> … <code>POP BX<\/code> / <code>POP CX<\/code> / <code>RET<\/code>", "<code>PUSH BX<\/code> / <code>PUSH CX<\/code> … <code>POP CX<\/code> / <code>POP BX<\/code> / <code>RET<\/code>", "<code>PUSH CX<\/code> … <code>POP CX<\/code> / <code>RET<\/code>, vì BX không bao giờ bị đổi"], "a": 2, "e": "Cất đúng các thanh ghi phải giữ và POP theo thứ tự ngược. Cất cả AX thì POP AX ghi đè kết quả; POP cùng thứ tự với PUSH làm BX và CX đổi chỗ (Bài 21)."}, {"q": "Vòng lặp dùng CX gọi thủ tục <code>in2so<\/code> 3 lần, nhưng chương trình in số mãi không dừng. Nguyên nhân hợp lý nhất?", "o": ["in2so dùng RET 4 thay vì RET nên SP sai", "in2so ghi vào CL (ví dụ MOV CL, 10 để chia) mà không cất CX", "Số lần lặp phải đặt trong CL chứ không phải CX", "DIV CL làm cờ ZF = 0 nên LOOP không dừng"], "a": 1, "e": "LOOP chỉ nhìn CX, không nhìn cờ. Thủ tục đặt lại CL = 10 sau mỗi lời gọi nên CX không về 0 (Ví dụ 6). RET 4 không có tham số sẽ làm hỏng SP, nhưng triệu chứng là RET/POP sai chứ không phải vòng lặp đều đặn."}]);

